<?php require_once __DIR__.'/auth.php'; $title='Gallery Management'; include 'admin-head.php'; include 'sidebar.php'; include 'topbar.php'; ?><main class="main"><?php $items=read_data('gallery');if($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['action']??'')==='delete'){$id=(int)$_POST['id'];$items=array_values(array_filter($items,fn($x)=>(int)($x['id']??0)!==$id));write_data('gallery',$items);redirect('gallery.php');}$image=trim($_POST['image']??'');if($u=save_uploaded_image('image_file'))$image=$u;if($image){$items[]=['id'=>next_id($items),'caption'=>trim($_POST['caption']??''),'image'=>$image];write_data('gallery',$items);}redirect('gallery.php');}?>
<div class="row g-4"><div class="col-lg-4"><div class="card shadow-sm p-4"><h5 class="fw-bold">Add Gallery Image</h5><form method="post" enctype="multipart/form-data"><label class="form-label mt-3">Caption</label><input name="caption" class="form-control"><label class="form-label mt-3">Image URL / filename</label><input name="image" class="form-control"><label class="form-label mt-3">Or upload image *</label><input type="file" name="image_file" class="form-control" accept="image/*"><button class="btn btn-success w-100 mt-4">Add Image</button></form></div></div><div class="col-lg-8"><div class="row g-3"><?php foreach($items as $x): ?><div class="col-6 col-md-4"><div class="card shadow-sm overflow-hidden"><img src="<?=e(admin_asset($x['image']))?>" style="height:170px;width:100%;object-fit:cover"><div class="card-body p-2"><small class="d-block mb-2"><?=e($x['caption']??'')?></small><form method="post" onsubmit="return confirm('Delete image?')"><input type="hidden" name="id" value="<?=$x['id']?>"><input type="hidden" name="action" value="delete"><button class="btn btn-sm btn-outline-danger w-100">Delete</button></form></div></div></div><?php endforeach;?></div></div></div><?php include 'admin-foot.php'; ?>